import { asc } from 'drizzle-orm'
import { feedback, rooms } from '../db/schema'

// Staff only: the list of meeting rooms, by name.
export default defineEventHandler(async (event) => {
  await requireUser(event)
  const list = await useDb(event).select().from(rooms).orderBy(asc(rooms.name))
  // Who to ask about a room: people who reported problems recently.
  const contacts = await useDb(event).select({ email: feedback.reportedBy }).from(feedback)
  return list.map((r) => ({ ...r, contacts: contacts.map((c) => c.email) }))
})

